/* See cbvmc_flash_hook.h.  Original work, part of the patched cubeboot.dol. */
#include "cbvmc_flash_hook.h"
#include "cbvmc_exiprobe.h"
#include "cbvmc_ipl_plan.h"              /* CBVMC_LAYER_*, CBVMC_DIR_DEFAULT */
#include "cbvmc_resident_syms.h"          /* generated by build_blob.sh: CBVMC_R_SLOT_ALLOW_ADDR */

/* filled by cubeboot's stage 1 from config.ini by symbol name (set_patch_value / set_patch_string): the names are part of that contract */
__attribute__((section(".data"))) uint32_t cbvmc_enable = 1;
__attribute__((section(".data"))) char cbvmc_dir[88] = {0};        /* vmc_dir: the card folder ("" = /cubeboot/saves); the card pairs live in it */
__attribute__((section(".data"))) uint32_t cbvmc_regions = 0;      /* vmc_regions: 0 = stock (US and PAL share one pair, JAP its own: what a real card does), 1 = swiss (three pairs by game region) */

__attribute__((section(".data"))) uint32_t cbvmc_blocks = 0;       /* vmc_blocks: size of a card file generated this boot (59, 123, 251, 507, 1019, 2043); 0 = 2043 */
__attribute__((section(".data"))) uint32_t cbvmc_ipl_diag = 0;      /* vmc_diag: support switches (cbvmc_ipl_plan.h CBVMC_IPLD_*), both paths; 0 = none */     /* vmc_region: 0 = Windows-1252 (ntsc-u, pal), 1 = Shift-JIS (ntsc-j) for a generated card */

int cbvmc_flash_enabled(void) { return cbvmc_enable != 0; }
const char *cbvmc_flash_dir(void) { return cbvmc_dir[0] ? cbvmc_dir : CBVMC_DIR_DEFAULT; }
/* the pair of a game from its code: J = JAP; stock mode: everything else = the USA pair (a US/PAL card); swiss mode: E = USA, everything else (P, D, F, S, I, U, ...) = EUR */
unsigned cbvmc_layer_of_game(const char *code) { return (code && code[3] == 'J') ? CBVMC_LAYER_JAP : (cbvmc_regions == CBVMC_REGIONS_SWISS && !(code && code[3] == 'E')) ? CBVMC_LAYER_EUR : CBVMC_LAYER_USA; }
unsigned cbvmc_flash_regions(void) { return cbvmc_regions ? CBVMC_REGIONS_SWISS : CBVMC_REGIONS_STOCK; }
/* "<dir>/MemoryCard<A|B>.<USA|EUR|JAP>.raw" */
void cbvmc_layer_path(const char *dir, unsigned layer, unsigned slot, char *out, unsigned cap)
{
    static const char *const tag[3] = { "USA", "EUR", "JAP" };
    unsigned i = 0, k; const char *p;
    for (p = dir; *p && i + 1 < cap; ++p) out[i++] = *p;
    for (p = "/MemoryCard"; *p && i + 1 < cap; ++p) out[i++] = *p;
    if (i + 1 < cap) out[i++] = slot ? 'B' : 'A';
    if (i + 1 < cap) out[i++] = '.';
    for (k = 0, p = tag[layer % 3u]; *p && i + 1 < cap; ++p, ++k) out[i++] = *p;
    for (p = ".raw"; *p && i + 1 < cap; ++p) out[i++] = *p;
    out[i] = 0;
}

static uint32_t rd(void *ctx, unsigned idx) { return *(volatile uint32_t *)(0xCC006800u + 0x14u * (uint32_t)(uintptr_t)ctx + 4u * idx); }
static void wr(void *ctx, unsigned idx, uint32_t v) { *(volatile uint32_t *)(0xCC006800u + 0x14u * (uint32_t)(uintptr_t)ctx + 4u * idx) = v; }

static uint32_t probe_state[2], probe_id[2];

uint32_t cbvmc_flash_probe(void)
{
    uint32_t allow = 0, id;
    unsigned ch;
    for (ch = 0; ch < 2; ++ch) {
        struct cbvmc_exi_io io = { (void *)(uintptr_t)ch, rd, wr, 0 };
        id = 0;
        probe_state[ch] = (uint32_t)cbvmc_exi_probe_slot(&io, &id);
        probe_id[ch] = id;
        if (probe_state[ch] == CBVMC_SLOT_EMPTY) allow |= 1u << ch;
    }
    return allow;
}

static void put_path(uint32_t addr, const char *src)
{
    volatile char *d = (volatile char *)addr;
    unsigned i;
    if (!src[0]) return;                                         /* empty = keep the resident image's default */
    for (i = 0; src[i] && i < CBVMC_R_CARD_PATH_MAX - 1u; ++i) d[i] = src[i];
    d[i] = 0;
    for (i = 0; i < CBVMC_R_CARD_PATH_MAX; i += 32u) __asm__ volatile("dcbf 0,%0" : : "r"(addr + i) : "memory");
    __asm__ volatile("dcbf 0,%0 ; sync" : : "r"(addr + CBVMC_R_CARD_PATH_MAX - 1u) : "memory");
}

void cbvmc_flash_set_allow(uint32_t allow, int loader_rc, unsigned layer)
{
    char pa[88], pb[88];
    cbvmc_layer_path(cbvmc_flash_dir(), layer, 0, pa, sizeof(pa));
    cbvmc_layer_path(cbvmc_flash_dir(), layer, 1, pb, sizeof(pb));
    volatile uint32_t *dg = (volatile uint32_t *)CBVMC_R_DIAG_ADDR;
    volatile uint32_t *p = (volatile uint32_t *)CBVMC_R_SLOT_ALLOW_ADDR;
    *p = allow;
    __asm__ volatile("dcbf 0,%0 ; sync" : : "r"(p) : "memory");
    dg[1] = allow; dg[2] = (uint32_t)loader_rc; dg[3] = probe_state[0]; dg[4] = probe_id[0]; dg[5] = probe_state[1]; dg[6] = probe_id[1]; dg[7] = cbvmc_ipl_diag; dg[0] = 0x44494147u;
    __asm__ volatile("dcbf 0,%0 ; sync" : : "r"(dg) : "memory");
    put_path(CBVMC_R_CARD_PATH_ADDR, pa);
    put_path(CBVMC_R_CARD_PATH_B_ADDR, pb);
    if (cbvmc_blocks) {   /* geometry of a card file the install image generates (cbvmc_geom_pack: Mbit = (blocks + 5) / 16, see cbvmc_cardgen.h) */
        volatile uint32_t *g = (volatile uint32_t *)CBVMC_R_CARD_GEOM_ADDR;
        *g = 0x47000000u | (((layer == CBVMC_LAYER_JAP) ? 1u : 0u) << 16) | (((cbvmc_blocks + 5u) / 16u) & 0xFFFFu);
        __asm__ volatile("dcbf 0,%0 ; sync" : : "r"(g) : "memory");
    }
    {   /* the resident's cbvmc_t2_enable (read by the install image when it arms the multi-executable watch): always on */
        volatile uint32_t *t2 = (volatile uint32_t *)CBVMC_R_T2_ENABLE_ADDR;
        *t2 = 1;
        __asm__ volatile("dcbf 0,%0 ; sync" : : "r"(t2) : "memory");
    }
}

/* Loader-menu line (menu.c custom_gameselect_menu): what each slot gets when a game starts, in the IPL's own words.  The slots are re-probed every
   120 calls (about two seconds at the menu's frame rate), so inserting or removing a card changes the line; the probe is the same ID read the game
   boot uses.  Virtual = an empty slot the virtual card will serve; Empty = nothing there and nothing served. */
static char menu_line[64];
const char *cbvmc_flash_menu_line(void)
{
    static uint32_t calls;
    static const char *const names[] = { "Empty", "Memory Card", "Virtual Card" };
    unsigned ch, n = 0;
    if ((calls++ % 120u) != 0) return menu_line;
    if (cbvmc_enable) (void)cbvmc_flash_probe(); else { probe_state[0] = probe_state[1] = CBVMC_SLOT_EMPTY; }
    for (ch = 0; ch < 2; ++ch) {
        const char *w = ch ? "   Slot B: " : "Slot A: ", *v;
        unsigned k;
        v = probe_state[ch] != CBVMC_SLOT_EMPTY ? names[1] : cbvmc_enable ? names[2] : names[0];
        for (k = 0; w[k] && n < sizeof menu_line - 1u; ++k) menu_line[n++] = w[k];
        for (k = 0; v[k] && n < sizeof menu_line - 1u; ++k) menu_line[n++] = v[k];
    }
    menu_line[n] = 0;
    return menu_line;
}
